type SystemsType = ModuleScript | Folder

-- 添加 TangSengDebuggerPlugins 服务
-- @param services IServiceCollection
-- @param context ContextType (区域)
-- @param system SystemsType (系统)
-- @param components { string }? (组件)
return function(services: IServiceCollection, system: SystemsType, components: { string }?)
	if type(system) ~= "userdata" then
		error(string.format("system 必须是 Instance 类型, 但收到的是 %s", type(system)))
	end

	services:AddTransient("ITangSengDebuggerPluginsProvider", function()
		return {
			Systems = { system },
			Components = components or {},
		}
	end)
end
